const firstSentence=t=>{const s=String(t||"").trim();return (s.match(/^(.+?[.!?])/)||[])[1]||s};
const cleaned=t=>String(t||"").split(/(?:This is not|This does not|The practice should not|The lesson is not|Rather than|It is not|not evidence that|does not mean|doesn’t mean|should not|shouldn’t)/i)[0].trim();
