const hasDefensiveFraming=t=>/(?:\bnot (?:simply|just|only|a |an |evidence|proof|something|one|be)|\bno single|\bshould not|\bdoes not|\bdoesn’t|\bdoesn't|\bnot automatically|\bnot a claim|\bnot a generic|\bnot one|\brather than)/i.test(String(t||''));
const positiveReflection=(a)=>{
 const raw=String(a.reflection||'').trim();
 if(!raw)return '';
 if(!hasDefensiveFraming(raw))return raw;
 const positive=raw
  .replace(/,\s*not only\b[^.!?]*[.!?]?/i,'.')
  .replace(/;\s*(?:it|this|that) (?:is|does|should)\b[^.!?]*[.!?]?/i,'.')
  .replace(/,\s*(?:not proof|not evidence|rather than)\b[^.!?]*[.!?]?/i,'.')
  .trim();
 if(!hasDefensiveFraming(positive)&&positive.length>22)return positive;
 const first=positive.split(/[;.!?]/)[0].trim().replace(/[, :]+$/,'');
 return first.length>22?first+'.':'';
};
