const mechanismFor=a=>{
 const t=(a.theme+' '+a.title).toLowerCase(),place=a.place,name=a.title.split(':')[0];
 if(/language|story|memory|history|song|voice|archive|poem/.test(t))return 'The memory here is carried in use: people learn the words or stories within a community, then meet them again when someone else brings them forward in '+place+'.';
 if(/craft|skill|apprentice|attention|patience|technology/.test(t))return 'A learner can watch an experienced person make small decisions at the material. Over time, those observations become practical judgement in '+place+'.';
 if(/dance|movement|coordination|performance|expression/.test(t))return 'Participants have to track timing and one another. The shared rhythm gives each person cues for when to move, wait or respond in '+name+'.';
 if(/governance|justice|accountability|power|rules|reconciliation/.test(t))return 'Voice and recognition shape the psychological experience here: who can speak, how others hear that person, and what makes a decision acceptable in '+place+'.';
 if(/grief|death|ritual|faith|belief|renewal|pilgrim|collective ritual/.test(t))return 'A shared sequence lets an individual response sit inside a local account of the event. It gives people a time and place to remember together in '+place+'.';
 if(/care|cooperation|trust|friendship|solidarity|belonging|community|hospitality/.test(t))return 'The practice makes care visible through what people do for one another. Its social meaning takes shape in those actions and the response they receive in '+place+'.';
 return 'The practice gives shared meaning a public form. Participants learn its cues as they take part and use them to understand what others are doing.';
};
const HENNA_OVERVIEW=[
 {heading:"A plant that leaves a temporary mark",paragraphs:[
  "Henna is a dye made from dried, powdered leaves of Lawsonia inermis. When the paste rests on skin, its dye compound lawsone binds with proteins in the outer layer. The stain starts orange, deepens over the next days and fades as the skin renews. A design therefore stays with the body after the application has ended.",
  "The first human uses of henna are difficult to date. Wikipedia’s overview gathers evidence of trade in Babylonia and use in ancient Egypt, including on hair, skin, nails and funerary materials. From North Africa and the Middle East, the plant and its uses travelled through wider regional networks."
 ]},
 {heading:"Preparation is part of the knowledge",paragraphs:[
  "Leaves are dried, ground and sifted before the paste is made. The liquids, tools and timing change by place and by intended use. UNESCO’s multinational record describes families teaching cultivation and application through observation and hands-on practice; the skill sits in the process as much as in the finished pattern.",
  "Wikipedia describes differences in technique across places, including the use of syringes in Morocco and cones in India. The material stays recognisable as henna while the method belongs to the people who have developed it."
 ]},
 {heading:"A shared name, many local practices",paragraphs:[
  "The 2024 UNESCO listing was jointly nominated by sixteen countries, including the United Arab Emirates. It describes henna in everyday adornment and at events around births and weddings, with songs, proverbs and poems accompanying some practices. The listing connects these forms while leaving room for local meanings.",
  "Wikipedia gives examples of that variation: Moroccan designs can echo geometric motifs found in traditional beading, while some Yemeni Jewish bridal practices unfold over several days. These examples belong to particular traditions; they cannot stand in for the whole region."
 ]},
 {heading:"What the practice can do psychologically",paragraphs:[
  "A mark on the body can make a life event visible. When the stain remains after a gathering, it carries a trace of the occasion into ordinary days. That is one psychological reading of henna’s temporary, embodied form.",
  "Preparation also creates a social setting. Someone makes the paste; a practitioner applies it; other people may watch, teach, sing or help. Attention and skill become ways of communicating recognition. The cultural sources describe these relationships; they do not measure a mental-health effect."
 ]},
 {heading:"Continuity and change",paragraphs:[
  "Henna may be an aesthetic choice, a family inheritance, a festive sign or several things at once. Who applies it, who receives it, and which designs are chosen shape the meaning. Contemporary salons and migration add new settings in which people adapt inherited forms."
 ]},
 {heading:"A useful distinction about the material",paragraphs:[
  "Products sold as “black henna” can contain p-phenylenediamine (PPD), a chemical used in some hair dyes. The FDA and NHS describe allergic reactions linked with PPD exposure. Plant-based henna and chemically darkened temporary tattoo products are different preparations, with different risks."
 ]},
 {heading:"A question to carry forward",paragraphs:[
  "The psychology of henna sits in how people learn a skill, mark an occasion and recognise one another through adornment. Which part of getting ready for an important event helps you feel accompanied?"
 ]}
];
const UAE_HENNA_STORY=[
 {heading:"The plant behind the mark",paragraphs:[
  "Henna is made from dried leaves of Lawsonia inermis. Wikipedia explains how lawsone, the plant’s dye compound, binds with proteins in the outer layer of skin. The stain appears orange, deepens over the next few days and fades as skin renews, usually over one to three weeks. The design therefore lasts beyond the moment of application.",
  "The plant’s earliest history is difficult to date. Wikipedia gathers evidence of henna trade in Babylonia and use in ancient Egypt, including on hair, skin, nails and funerary materials. Dubai’s local sources give the wider history a present-day setting: body art remains part of the city’s beauty culture, while UAE heritage records preserve how families prepared and used henna."
 ]},
 {heading:"Growing and preparing henna in the UAE",paragraphs:[
  "Women interviewed for Abu Dhabi’s heritage register remember henna growing at the edges of palm farms. They describe cutting branches so the plant would grow again, harvesting before it seeded, drying leaves away from direct sunlight, then pounding and sifting them through a cloth called sheila or wegaya.",
  "For use, the powder was kneaded with boiling water and dried lemon and left to rest. These steps depend on practical judgement: knowing when leaves are ready, how finely to sift them and when the paste can be applied. The plant, tools and local words are all part of the knowledge passed on."
 ]},
 {heading:"Design vocabulary and the al-muhannya",paragraphs:[
  "The Abu Dhabi register preserves names for several designs. Ghamsa covers the front and back of the hand; gussa marks the fingers and part or all of the palm. Other forms include shera’a, a triangle; rawayeb, fingertip marks; tila, a marble-like dot; and kazoa, shaped like a bean. The UAE Ministry of Culture records al-kazu as a cashew-shaped motif that also appears in textiles and older decorative patterns.",
  "The practitioner is known as al-muhannya or al-hannaya. Abu Dhabi’s record describes her as a woman recognised in the community for decorating other women’s hands and feet. The work carries technique and reputation, and the practitioner receives a fee. Henna is a skilled craft as well as an adornment."
 ]},
 {heading:"A wedding sequence in Al Ain",paragraphs:[
  "One heritage account follows the bride’s procession in the Al Ain oases. Preparation begins about a week before the wedding, when the bride is treated with neel and warss. Her friends gather to meet responsibilities around her and sing, especially during the henna ceremony. The muhannya oversees the adornment, and the bride remains out of public view until the wedding day.",
  "That sequence gives the transition a social shape. The bride is surrounded by people who know what the event means and have roles in preparing for it. Henna marks an approaching marriage on the body while the gathering makes the change recognisable to the people around her."
 ]},
 {heading:"Henna in Dubai now",paragraphs:[
  "Dubai’s official culture guide places henna artists in beauty salons, shopping centres, souks and desert camps. It also describes henna as part of weddings and public celebrations such as Eid and UAE National Day. In the city, the practice moves between family occasions, heritage events and commercial settings.",
  "That range matters psychologically. A wedding henna night can organise support around a bride; a salon visit can make body art a personal choice; a public heritage event can present the practice to a wider audience. The meaning comes from the setting and relationships, not from the stain alone."
 ]},
 {heading:"A practice that adapts",paragraphs:[
  "The heritage register describes modern salon designs combining local, Indian and Sudanese influences. The National’s reporting on Emirati weddings also records different choices: some brides have friends or practitioners apply henna, while others choose to do it themselves. The practice keeps its place in local life as people change who applies it, which designs they choose and where it happens.",
  "One UAE narrator, Al Hadh Al Kuwaiti, recalls a saying: “The henna of the day is adornment, the henna of the night is treasury.” It holds public beauty and remembered household use in a single line. The saying shows how the practice can hold several meanings at once."
 ]},
 {heading:"Plant henna and “black henna”",paragraphs:[
  "Natural henna stains reddish brown. Wikipedia distinguishes it from products marketed as “black henna,” which may contain PPD, a chemical used in some hair dyes. The FDA and NHS describe allergic reactions associated with PPD exposure. The distinction helps explain what material is being used without confusing a plant dye with a chemically darkened temporary tattoo."
 ]},
 {heading:"What the sources let us say",paragraphs:[
  "Dubai tourism material documents the practice’s current public settings; UAE heritage records give detail on cultivation, design names, practitioners and an Al Ain wedding sequence. A psychology lens can trace embodied identity, shared attention, social recognition and the transition into marriage through those details. These sources document cultural practice and testimony; they do not measure a mental-health outcome.",
  "Which part of preparing for an important change helps you feel accompanied?"
 ]}
];
const paragraphsFor=a=>{
 if(a.id==='uae-henna')return UAE_HENNA_STORY;
 if(a.id==='henna-rituals')return HENNA_OVERVIEW;
 const studies=LOCAL[a.id]||[];
 const opening=humanText(a.body?.[0]||'');
 const experience=humanText(a.body?.[1]||'');
 const discussion=humanText(debateFor(a));
 const reflection=humanText(positiveReflection(a));
 const sections=[
  {heading:'The practice in its place',paragraphs:[opening,noteFor(a)].filter(Boolean)},
  {heading:'What participation makes possible',paragraphs:[experience,mechanismFor(a)].filter(Boolean)}
 ];
 if(studies.length)sections.push({heading:'Research from this place',paragraphs:studies.map(study=>study.method+' '+study.finding)});
 sections.push({heading:'Questions that stay with the practice',paragraphs:[discussion,reflection,a.question].filter(Boolean)});
 return sections;
};
export const CULTURE_INVESTIGATIONS=Object.freeze(Object.fromEntries(CULTURE_ARTICLES.map(a=>[a.id,Object.freeze({
 sections:Object.freeze(paragraphsFor(a).map(s=>Object.freeze({...s,paragraphs:Object.freeze(s.paragraphs)}))),
 evidence:Object.freeze([...(LOCAL[a.id]||[]),...(EXTRA_EVIDENCE[a.id]||[]),...((EXTRA_EVIDENCE[a.id]||[]).some(item=>item.url===a.source.url)?[]:[culturalSource(a)])].map(item=>Object.freeze(item)))
})])));
